<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE){$https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$https,'httponly'=>true,'samesite'=>'Lax']);session_start();}
require __DIR__ . '/db.php';
if(empty($_SESSION['install_csrf']))$_SESSION['install_csrf']=bin2hex(random_bytes(32));
$done=false;$error='';
try{$done=(int)db()->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='offices'")->fetchColumn()>0;}catch(Throwable $e){$error='Koneksi database gagal. Periksa config.php.';}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$done&&!$error){
    $office=trim($_POST['office']??'');$slug=strtolower(trim($_POST['slug']??''));$name=trim($_POST['admin_name']??'');$username=trim($_POST['username']??'');$password=(string)($_POST['password']??'');
    if(!hash_equals($_SESSION['install_csrf']??'',(string)($_POST['csrf']??'')))$error='Sesi formulir instalasi tidak valid. Muat ulang halaman.';
    elseif(!$office||!$slug||!$name||!$username||strlen($password)<10||!preg_match('/^[a-z0-9-]+$/',$slug))$error='Lengkapi semua kolom. Kata sandi minimal 10 karakter dan slug hanya huruf kecil, angka, atau tanda hubung.';
    else{try{$sql=file_get_contents(__DIR__.'/schema.sql');foreach(array_filter(array_map('trim',explode(';',$sql))) as $statement)db()->exec($statement);$q=db()->prepare('INSERT INTO offices(name,slug) VALUES(?,?)');$q->execute([$office,$slug]);$officeId=(int)db()->lastInsertId();$q=db()->prepare('INSERT INTO users(office_id,name,username,password_hash,role) VALUES(?,?,?,?,?)');$q->execute([$officeId,$name,$username,password_hash($password,PASSWORD_DEFAULT),'admin']);$done=true;}catch(Throwable $e){$error='Instalasi gagal. Periksa hak akses database dan pastikan aplikasi belum pernah dipasang.';}}
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalasi Aplikasi Antrean</title><link rel="stylesheet" href="assets/style.css"></head><body class="installer"><main class="install-card"><div class="brand-mark">A</div><p class="eyebrow">PENYIAPAN APLIKASI</p><h1>Instalasi Antrean</h1><?php if($done): ?><div class="notice success">Database dan akun administrator sudah siap.</div><p>Hapus atau blokir <code>install.php</code> setelah instalasi, lalu masuk melalui halaman petugas.</p><a class="button primary" href="index.php?page=operator">Buka halaman masuk</a><?php else: ?><p>Pastikan database sudah dibuat dan pengaturan koneksi di <code>config.php</code> benar.</p><?php if($error): ?><div class="notice error"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif; ?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['install_csrf'],ENT_QUOTES,'UTF-8')?>"><label>Nama kantor<input name="office" required placeholder="Kantor Pelayanan Utama"></label><label>Slug kantor<input name="slug" required placeholder="kantor-utama" pattern="[a-z0-9-]+"><small>Dipakai pada alamat kios dan layar, misalnya ?page=kiosk&amp;office=kantor-utama</small></label><label>Nama administrator<input name="admin_name" required></label><label>Username administrator<input name="username" required autocomplete="username"></label><label>Kata sandi<input name="password" type="password" minlength="10" required autocomplete="new-password"><small>Minimal 10 karakter.</small></label><button class="button primary">Pasang aplikasi</button></form><?php endif; ?></main></body></html>
